python3 -c '
import pandas as pd
import ast
import re

tasks = pd.read_csv("/app/dataset/tasks.csv")
task_pay = dict(zip(tasks.task_id, tasks.pay_per_completion))
ts = pd.read_csv("/app/dataset/timesheet.csv")

def diff(s1, s2):
    return sum(1 for a, b in zip(s1, s2) if a != b) + abs(len(s1) - len(s2))

for _, row in ts.iterrows():
    s = str(row["performed_tasks"]).strip()
    if not s.endswith("]"): s += "]"
    if not s.startswith("["): s = "[" + s
    try:
        tasks_list = ast.literal_eval(s)
    except:
        tasks_list = [int(x) for x in re.findall(r"\d+", s)]

    expected = 0
    invalid = []
    for t in tasks_list:
        if t in task_pay:
            expected += task_pay[t]
        else:
            invalid.append(t)

    if invalid:
        missing = row["bonus"] - expected
        print(f"Row {row.name} invalid {invalid} missing_bonus {missing}. Candidates:")
        for inv_t in invalid:
            cands = []
            for t_id, pay in task_pay.items():
                if pay == missing:
                    cands.append((t_id, diff(str(inv_t), str(t_id))))
            cands.sort(key=lambda x: x[1])
            print(f"  {inv_t} -> {cands[:3]}")

    if _ > 200: break
' | head -n 30

