args.command:
python3 -c '
import pandas as pd
import ast, re

def lev(s1, s2):
    if len(s1) < len(s2):
        return lev(s2, s1)
    if len(s2) == 0:
        return len(s1)
    prev = range(len(s2) + 1)
    for i, c1 in enumerate(s1):
        curr = [i + 1]
        for j, c2 in enumerate(s2):
            curr.append(min(prev[j + 1] + 1, curr[j] + 1, prev[j] + (c1 != c2)))
        prev = curr
    return prev[-1]

tasks = pd.read_csv("/app/dataset/tasks.csv")
valid_tasks = set(tasks.task_id.tolist())
valid_tasks_str = [str(t) for t in valid_tasks]

ts = pd.read_csv("/app/dataset/timesheet.csv")

invalid_tasks = set()
for s in ts.performed_tasks:
    s = str(s).strip()
    if not s.endswith("]"): s += "]"
    if not s.startswith("["): s = "[" + s
    try:
        t_list = ast.literal_eval(s)
    except:
        t_list = [int(x) for x in re.findall(r"\d+", s)]
    invalid_tasks.update(str(t) for t in t_list if t not in valid_tasks)

unique_count = 0
ambig_count = 0
for inv in invalid_tasks:
    dists = []
    for vt in valid_tasks_str:
        dists.append((vt, lev(inv, vt)))
    dists.sort(key=lambda x: x[1])
    min_d = dists[0][1]
    best = [vt for vt, d in dists if d == min_d]
    if len(best) == 1:
        unique_count += 1
    else:
        ambig_count += 1
print(f"Unique match: {unique_count}, Ambiguous: {ambig_count}")
'

