import pandas as pd

ts = pd.read_csv("/app/dataset/timesheet.csv")
invalid_emps = ts.employee_id.astype(str).str.zfill(11)

emp = pd.read_csv("/app/dataset/employees.csv")
valid_pesels = [str(p).zfill(11) for p in emp.PESEL]

def lev(s1, s2):
    if len(s1) < len(s2): return lev(s2, s1)
    if len(s2) == 0: return len(s1)
    prev = range(len(s2) + 1)
    for i, c1 in enumerate(s1):
        curr = [i + 1]
        for j, c2 in enumerate(s2):
            curr.append(min(prev[j + 1] + 1, curr[j] + 1, prev[j] + (c1 != c2)))
        prev = curr
    return prev[-1]

for e in invalid_emps:
    if e not in valid_pesels:
        dists = [(vp, lev(e, vp)) for vp in valid_pesels]
        dists.sort(key=lambda x: x[1])
        print(f"Corrupted: {e} -> Corrected: {dists[0][0]}")
'

